bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
const publisher=readFileSync('/opt/videobot/src/telegram/paidListingPublisher.mjs','utf8');
const media=readFileSync('/opt/videobot/src/telegram/paidMedia.mjs','utf8');
const flags={
nativeSend:publisher.includes("sendPaidMedia"),
nativePrice:media.includes("star_count:priceStars"),
verifiedPrice:publisher.includes("paidResult.paid_media.star_count")||publisher.includes("paidResult?.paid_media?.star_count"),
verifiedMediaCount:publisher.includes("paid_media.paid_media.length"),
durableAck:publisher.includes("recordPaid("),
receiptUnknown:publisher.includes("markUnknown(")
};
console.log(JSON.stringify(flags));
if(!flags.nativeSend||!flags.nativePrice)process.exitCode=61;
JS
